pre_eq <- function(h) { d <- html_parse(h); md <- html_markdown(d); back <- html_parse(commonmark::markdown_html(md)); a <- html_text(html_elements(d, "pre")); b <- sub("\n$", "", html_text(html_elements(back, "pre"))); cat(if (identical(sub("\n$","",a), b)) "ok  " else "DIFF", encodeString(h), "\n   md:", encodeString(md), "\n   pre0:", encodeString(a), "\n   pre1:", encodeString(b), "\n") }
for (h in c('<ul><li>a<pre>l1\n\n  l3\n</pre></ul>', '<blockquote><pre>\n\nx\n\n\n</pre></blockquote>', '<ol><li><ul><li><pre>a\n````\n~~~\nb</pre></ul></ol>', '<pre>   lead\n\ttab</pre>', '<pre>a\r\nb</pre>', '<pre>x  \n</pre>', '<pre>\n</pre>', '<pre> </pre>', '<pre>a\n\n</pre>', '<pre><code>a\n</code></pre>', '<pre>a&nbsp;b</pre>', '<pre class="language-">x</pre>', '<pre class="language-r\nx">x</pre>', '<p>a</p><pre>b</pre>c', '<li><pre>x</pre>', '<pre><b>bold</b> <a href=u>l</a><script>s</script><img src=i alt=A></pre>', '<td><pre>x</pre>', '<table><tr><td><pre>x\ny</pre><td>b</table>', '<pre>a<pre>b</pre>c</pre>', '<pre>a\n<p>para</p>\nb</pre>')) pre_eq(h)
for (h in c('<p>Hi!</p><a href=u>x</a>', '<p><b>Hi!</b><a href=u>x</a></p>', '<p>a !<a href=u>x</a></p>', '<p>!<img src=i alt=a></p>', '<p>snake<i>_</i>case a<i>_b_</i>c</p>', '<p><i>a</i>b<i>c</i></p>', '<p>a<i>b</i>c<b>d</b>e</p>', '<p><i>a </i><b> b</b></p>', '<p><b>a</b> <b>b</b></p>', '<p><i>a,</i> b</p>', '<p>a <i>,b</i></p>', '<p>a<i>,b</i></p>', '<p><i>a,</i>b</p>', '<p><b>&quot;a&quot;</b>b</p>', '<p>a<b>&quot;b&quot;</b></p>', '<p>é<b>b</b>é</p>', '<p>中<b>文</b>字</p>', '<p>a<b>。b</b></p>', '<p><b>a</b><br><b>b</b></p>', '<p><b>a<br>b</b></p>', '<p><b>a<br></b>b</p>', '<p><i><br>a</i></p>', '<h2><b>a</b><i>b</i></h2>', '<ul><li><b>a</b><li><i>b</i></ul>', '<p><del>a</del></p>')) sigs2 <- mk(h)
